[
    {
        "title": "设变量",
        "description": "设行驶时间为 $x$ 小时，剩余油量为 $y$ 升。根据题意，$y$ 与 $x$ 之间的关系是一次函数。",
        "bubbleText": "先把两个变化的量分别用字母表示，后面就能用一次函数来描述油量变化。",
        "bubblePos": {
            "x": 410.0,
            "y": 90.0
        },
        "arrowTarget": {
            "x": 410.0,
            "y": 480.0
        }
    },
    {
        "title": "描出两点",
        "description": "行驶 $2$ 小时、剩余油量 $48$ 升，对应点 $A(2,48)$；行驶 $5$ 小时、剩余油量 $30$ 升，对应点 $B(5,30)$。",
        "bubbleText": "时间是横坐标，油量是纵坐标，所以两组数据在图上对应两个点。",
        "bubblePos": {
            "x": 410.0,
            "y": 90.0
        },
        "arrowTarget": {
            "x": 270.0,
            "y": 288.0
        }
    },
    {
        "title": "求斜率",
        "description": "一次函数的斜率为 $m=\\frac{30-48}{5-2}=\\frac{-18}{3}=-6$。",
        "bubbleText": "油量每增加 1 小时减少 6 升，因此斜率是 $-6$。",
        "bubblePos": {
            "x": 410.0,
            "y": 90.0
        },
        "arrowTarget": {
            "x": 400.0,
            "y": 340.0
        }
    },
    {
        "title": "设函数式",
        "description": "设一次函数解析式为 $y=mx+n$。将 $m=-6$ 代入，得 $y=-6x+n$。",
        "bubbleText": "先确定斜率，再保留截距 $n$，这是一次函数的标准求式方法。",
        "bubblePos": {
            "x": 410.0,
            "y": 90.0
        },
        "arrowTarget": {
            "x": 150.0,
            "y": 240.0
        }
    },
    {
        "title": "求截距",
        "description": "将点 $A(2,48)$ 代入 $y=-6x+n$，得 $48=-6\\times2+n$，解得 $n=60$，所以函数解析式为 $y=-6x+60$。",
        "bubbleText": "把已知点代入，就能求出油量函数在纵轴上的截距。",
        "bubblePos": {
            "x": 410.0,
            "y": 90.0
        },
        "arrowTarget": {
            "x": 270.0,
            "y": 288.0
        }
    },
    {
        "title": "求初始油量",
        "description": "加满油时尚未行驶，故 $x=0$。代入解析式，得 $y=-6\\times0+60=60$，所以初始油量为 $60$ 升。",
        "bubbleText": "加满油对应行驶时间为 0，把 $x=0$ 代入即可得到初始油量。",
        "bubblePos": {
            "x": 410.0,
            "y": 90.0
        },
        "arrowTarget": {
            "x": 150.0,
            "y": 240.0
        }
    },
    {
        "title": "检验作答",
        "description": "检验：当 $x=2$ 时，$y=-6\\times2+60=48$；当 $x=5$ 时，$y=-6\\times5+60=30$，均符合题意。因此，这辆汽车加满油时油箱中有 $60$ 升油。",
        "bubbleText": "两个已知时刻都能算回题目给出的油量，答案正确。",
        "bubblePos": {
            "x": 410.0,
            "y": 90.0
        },
        "arrowTarget": {
            "x": 450.0,
            "y": 360.0
        }
    }
]
